"""The commands that make labels, references, captures and runs from outside, as operations that run as jobs (RFC-032 step 9
P3, step 5): a sheet of items to label (an artifact), a filled sheet or a label folder read back (an upload), labels from a
run or from a capture's outcomes, the reference sets promoted from labels, runs imported from another tool, a capture of a
production system's records and what is made from one. Each is a POST on its resource and answers 202 with the job."""

from __future__ import annotations

from evaluation_harness.ops import legacy
from evaluation_harness.ops.registry import Op

OPS = (
    Op("label-sheet", "work", "a sheet of a dataset's items to label, with what production or an arm decided",
       "POST", "/datasets/{dataset}/label-sheets", "evaluation_harness.label_sheet:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("dataset_id", "out",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset whose items the sheet lists"},
           "out": {"type": "string", "format": "path", "description": "the sheet to write (.csv)", "x-file": "artifact"},
           "items": {"type": "string", "enum": ["unlabelled", "all", "disagree"], "default": "unlabelled", "description": "which items: those with no label yet, all, or those the runs disagree on"},
           "item": {"type": "array", "items": {"type": "string"}, "description": "exactly this item (repeatable)"},
           "runs": {"type": "string", "default": "", "description": "runs (or systems) whose decisions the sheet shows, comma-separated"},
           "propose": {"type": "string", "description": "a label set (by name, on this dataset) or a run whose answers are proposed"},
           "choices": {"type": "string", "description": "the allowed answers, comma-separated (e.g. file,dismiss,escalate): written into the label column's header; label-import refuses any other"},
       }),
    Op("label-import", "work", "a filled label sheet as a person's label set",
       "POST", "/datasets/{dataset}/label-sets/{set}", "evaluation_harness.label_import:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("sheet", "dataset_id", "set",), inputs={
           "sheet": {"type": "string", "format": "path", "description": "the filled sheet (.csv, as label-sheet writes it), or a folder of <item_id>.txt", "x-file": "upload"},
           "dataset_id": {"type": "string", "description": "the dataset the labels are on"},
           "set": {"type": "string", "description": "the label set's name (lowercase, _ . -)"},
           "guideline": {"type": "string", "format": "path", "description": "a file: the instructions the labeller followed (its path and sha256 are recorded)", "x-file": "upload"},
       }),
    Op("sheet-import", "work", "a sheet filled elsewhere, read back: labels as a label set, picks or scores as judged runs",
       "POST", "/datasets/{dataset}/sheets/import", "evaluation_harness.sheet_import:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("sheet", "dataset_id",), inputs={
           "sheet": {"type": "string", "format": "path", "description": "the filled sheet (.csv)", "x-file": "upload"},
           "dataset_id": {"type": "string", "description": "the dataset the sheet is of"},
           "kind": {"type": "string", "enum": ["person", "model"], "default": "person", "description": "who filled it (default: person)"},
           "set": {"type": "string", "description": "the label set's name, for a filled `label` column"},
           "scorer": {"type": "string", "description": "the name of the judged scores (read as judged/<scorer>; key <scorer>@none under each arm's run), for `pick`/`score:`"},
           "tags": {"type": "string", "description": "the tag set's name, for filled `failure_modes:` columns (data/tags/<dataset>/<name>/)"},
           "modes": {"type": "string", "description": "with --tags: the failure-mode list the tags name (data/failure-modes/<id>.yaml)"},
           "key": {"type": "string", "format": "path", "description": "the sheet's key (default: sheet.key.json beside it)", "x-file": "upload"},
           "export_job": {"type": "string", "pattern": "^[0-9]{8}T[0-9]{6}-[0-9a-f]{6}$", "description": "the sheet-export job that wrote the sheet: its key is read where that job kept it, so a blind sheet's key never leaves the project (not with --key)"},
           "guideline": {"type": "string", "format": "path", "description": "with --set, a file: the instructions the labeller followed (its path and sha256 are recorded)", "x-file": "upload"},
       }),
    Op("sheet-export", "work", "a dataset's sheet written as a CSV to fill in: what each run wrote and scored beside every item, the columns to fill (--fill label|pick|scores|tags)",
       "POST", "/datasets/{dataset}/sheets", "evaluation_harness.sheet_export:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("dataset_id", "runs", "csv"), inputs={
           "dataset_id": {"type": "string", "description": "the dataset whose items are the rows"},
           "runs": {"type": "string", "description": "runs: run ids or system ids (their latest run on the dataset), comma-separated; the first is production's"},
           "csv": {"type": "string", "format": "path", "x-metavar": "FILE", "description": "the CSV to write (UTF-8 with the mark Excel needs); a blind fill's key is written beside it (sheet.key.json), and a job keeps the key: its files never serve one", "x-file": "artifact"},
           "metric": {"type": "string", "description": "default: the metric that decides on the dataset: its goal's measure, else the arms' primary metric"},
           "label": {"type": "string", "default": "", "description": "the label system ids are looked up under (default: the plain arm)"},
           "where": {"type": "array", "items": {"type": "string"}, "x-metavar": "FIELD:VALUE", "description": "FIELD:VALUE or FIELD:LO..HI, keep only matching items (repeatable)"},
           "disagree": {"type": "boolean", "description": "only the items where a run decided differently from the first"},
           "split": {"type": "boolean", "description": "only the items the candidates (the runs after the first) decided differently among themselves"},
           "wrong_against": {"type": "string", "x-metavar": "SET", "description": "only the items where the first run's decision is not this label set's (SET or DATASET/SET)"},
           "new_vs": {"type": "string", "x-metavar": "DATASET", "description": "only the items with a field value this dataset has never had"},
           "unlabelled": {"type": "boolean", "description": "only the items no label set labels yet"},
           "judge_disagrees": {"type": "boolean", "description": "only the items where a judge on a validation disagrees with the people's ratings (its term of the validation figure is under chance)"},
           "scores_only": {"type": "boolean", "description": "leave the runs' outputs out, keep their scores"},
           "fill": {"type": "string", "enum": ["label", "pick", "scores", "tags"], "description": "add the columns to fill. label: label, also right, note. pick, scores: the outputs as blind columns A, B, C... shuffled per row, a key beside the sheet (sheet.key.json), the rubric as its first row; tags: a failure_modes column beside each arm's output (with --modes), a key beside the sheet; evh sheet-import --sheet reads it back"},
           "modes": {"type": "string", "description": "with --fill tags: the failure-mode list the tags name (data/failure-modes/<id>.yaml)"},
           "choices": {"type": "string", "description": "with --fill label: the allowed answers, comma-separated (e.g. file,dismiss,escalate), written into the label column's header"},
           "seed": {"type": "integer", "description": "with --fill pick or scores: the shuffle's seed (default 0)"},
           "rubric": {"type": "string", "format": "path", "description": "with --fill pick or scores: a file saying what to judge (default: a plain one)", "x-file": "upload"},
           "scale": {"type": "string", "description": "with --fill scores: the scores' range, LO..HI (default 1..5)"},
       }),
    Op("label-from-run", "work", "a finished run's outputs as a model's label set (calls nothing)",
       "POST", "/runs/{run}/label-sets", "evaluation_harness.label_from_run:body", "",
       locks=(), locks_fn="evaluation_harness.ops.locks:run_dataset_locks", required=("run", "set",), inputs={
           "run": {"type": "string", "description": "the run whose outputs become the labels"},
           "set": {"type": "string", "description": "the label set's name (lowercase, _ . -)"},
           "guideline": {"type": "string", "format": "path", "description": "a file: the prompt or instructions the model labelled by (its path and sha256 are recorded)", "x-file": "upload"},
           "allow_cut_off": {"type": "boolean", "description": "keep outputs that stopped at max_tokens"},
           "allow_dirty": {"type": "boolean", "description": "a run from a dirty tree"},
           "allow_unknown_build": {"type": "boolean", "description": "a run whose build is unknown"},
           "not_redistributed": {"type": "boolean", "description": "keep the texts out of git (a .gitignore beside them); labels.json says how to rebuild them"},
       }),
    Op("label-from-capture", "work", "rules over a capture's recorded outcomes as a rule label set",
       "POST", "/captures/{capture}/label-sets", "evaluation_harness.label_from_capture:body", "",
       locks=(("dataset:{dataset_id}", True),), required=("dataset_id", "capture", "map", "set",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset whose items are labelled"},
           "capture": {"type": "string", "description": "the capture whose records hold the decisions (and outcomes)"},
           "map": {"type": "string", "format": "path", "description": "the mapping: YAML rules", "x-file": "upload"},
           "set": {"type": "string", "description": "the label set's name (lowercase, _ . -)"},
           "outcomes": legacy.OUTCOMES,
           "from_set": {"type": "string", "description": "a relabel: keep this earlier set's labels and add what matured since"},
           "keep_vanished": {"type": "boolean", "description": "with --from-set: keep an earlier label today's rules no longer give (said), instead of refusing"},
           "reproduced_by": {"type": "string", "description": "a replay run at the recorded versions (RFC-030): keep a label only where it reproduces production's decision (with --production); a version dated by commit time counts as approximate (RFC-031 X2)"},
           "production": {"type": "string", "description": "with --reproduced-by: production's recorded run"},
           "action_field": {"type": "string", "description": "the record field holding production's action, for rules with under: action (RFC-031)"},
       }),
    Op("reference-promote", "decision", "promote a label set's labels to a reference set, at a tier, with a reason",
       "POST", "/datasets/{dataset}/references", "evaluation_harness.reference_promote:body", "",
       locks=(("dataset:{dataset_id}", True),), why="reason", parts={"dataset": "dataset_id"}, required=("dataset_id", "labels", "tier", "reason",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset the reference set is for"},
           "labels": {"type": "string", "description": "SET (made on this dataset) or DATASET/SET"},
           "tier": {"type": "string", "enum": ["gold", "silver"], "description": ""},
           "reason": {"type": "string", "description": "why these labels are the yardstick (a sentence)"},
           "items": {"type": "array", "items": {"type": "string"}, "description": "only this item, by its id (repeatable; default all labelled)", "x-file": "no"},
           "name": {"type": "string", "description": "the reference set's name under its tier (default: the dataset's id)"},
       }),
    Op("reference-manifest", "decision", "the checksummed manifest of a reference set a fetch script built",
       "POST", "/references/manifest", "evaluation_harness.reference_manifest:body", "",
       locks=(("dataset:{dataset_id}", True),), why="reason", required=("reference_id", "source", "labelled_by", "reason",), inputs={
           "reference_id": {"type": "string", "description": "<tier>/<dataset_id>, e.g. gold/ag_news_200"},
           "source": {"type": "string", "description": "how to rebuild its text, e.g. examples/classification-ag-news/fetch.py"},
           "not_redistributed": {"type": "boolean", "description": "the text is not committed (its licence, or the project's choice); the manifest is"},
           "dataset_id": {"type": "string", "description": "the dataset it is a reference set for, when its name is not the dataset's (a second gold for one dataset)"},
           "labelled_by": {"type": "string", "description": "whose labels they are, e.g. \"the dataset's authors\""},
           "kind": {"type": "string", "enum": ["person", "model", "rule"], "default": "person", "description": "the labels' source"},
           "reason": {"type": "string", "description": "why these labels are the yardstick (a sentence)"},
       }),
    Op("import-run", "work", "per-item scores from another tool, as a run the tests can read",
       "POST", "/datasets/{dataset}/runs/import", "evaluation_harness.import_run:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("dataset_id", "system_id", "scores", "primary_metric", "build_ref", "source", "scorer_id",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset the scores are on"},
           "system_id": {"type": "string", "description": "the arm's name, as tests will refer to it"},
           "scores": {"type": "string", "format": "path", "description": "JSONL: item_id + numeric metrics", "x-file": "upload"},
           "primary_metric": {"type": "string", "description": "the metric the run is judged by"},
           "asc": {"type": "boolean", "description": "lower is better for the primary metric"},
           "build_ref": {"type": "string", "description": "identity of the system that produced the outputs (commit, version, digest)"},
           "source": {"type": "string", "description": "where the outputs and scores came from"},
           "scorer_id": {"type": "string", "description": "the scoring code that produced the numbers"},
           "scorer_file": {"type": "array", "format": "path", "items": {"type": "string"}, "description": "a file of that scoring code (repeatable, in a fixed order); hashed by what it does, docstrings and comments not counted, and recorded as the instrument", "x-file": "upload"},
           "reference_id": {"type": "string", "description": "the references the scores are against, e.g. gold/my_v1"},
           "reference_tier": {"type": "string", "enum": ["gold", "silver"], "description": "the tier of the references the scores are against"},
           "metric_kind": {"type": "array", "items": {"type": "string"}, "x-metavar": "METRIC=KIND", "description": "quality | descriptive | cost | speed (repeatable)"},
           "allow_subset": {"type": "boolean", "description": "accept scores for only part of the dataset, recorded as coverage"},
           "run_id": {"type": "string", "description": "default: <system-id>_<timestamp>"},
           "goal": {"type": "string", "description": "the goal this run answers (data/goals/<goal_id>.yaml); required from the date data/goals/policy.yaml gives (one line there: required_from: YYYY-MM-DD; the file is yours to create)"},
       }),
    Op("capture", "work", "keep a production system's records as a capture (data/captures/)",
       "POST", "/captures/{capture}", "evaluation_harness.capture:body", "",
       locks=(("captures", True),), required=("importer", "query", "capture",), inputs={
           "importer": {"type": "string", "description": "a built-in name or a project importer's name (a code file, path.py:Class, is never taken by a job)", "pattern": "^[a-z0-9][a-z0-9_]*$"},
           "query": {"type": "string", "description": "the importer's query: JSON (a file, @file.json, is never taken by a job)", "pattern": "^(?!@)"},
           "capture": {"type": "string", "description": "the capture's id: lowercase_with_underscores"},
           "since_capture": {"type": "string", "x-metavar": "CAPTURE", "description": "continue from an earlier capture"},
           "force": {"type": "boolean", "description": "replace an existing capture of the same id"},
           "late": {"type": "boolean", "description": "keep records older than the window's since, listed as late arrivals"},
           "sample_rate": {"type": "number", "x-metavar": "R", "description": "keep a share R (0 < R <= 1) of the records"},
           "seed": {"type": "integer", "description": "with --sample-rate: the seed, so the same sample is drawn again"},
       }),
    Op("capture-restore", "work", "read a capture's records again from its source, and the items of the datasets made from it, every hash checked",
       "POST", "/captures/{capture}/restore", "evaluation_harness.capture_restore:body", "",
       locks=(("captures", True),), required=("capture",), inputs={
           "capture": {"type": "string", "description": "the capture's id"},
           "query": {"type": "array", "description": "replace one key of the recorded query (repeatable), e.g. path=exports/decisions.jsonl", "items": {"type": "string"}, "x-metavar": "KEY=VALUE"},
           "force": {"type": "boolean", "description": "replace a records/ whose files do not match"},
       }),
    Op("dataset-from-capture", "work", "make a dataset version from a capture: choose records, freeze their bodies as items",
       "POST", "/captures/{capture}/datasets", "evaluation_harness.dataset_from_capture:body", "",
       locks=(("captures", False), ("dataset:{dataset_id}", True)), required=("capture", "dataset_id",), inputs={
           "capture": {"type": "string", "description": "the capture's id (data/captures/<id>)"},
           "dataset_id": {"type": "string", "description": "lowercase_with_underscores"},
           "from": {"type": "string", "x-metavar": "DATASET_ID", "description": "the version this one grows from"},
           "where": {"type": "array", "items": {"type": "string"}, "description": "FIELD:VALUE keeps matching records, FIELD!=VALUE drops them (repeatable; missing is \"\")"},
           "one_per": {"type": "string", "x-metavar": "FIELD", "description": "keep one record per value of this field, the newest"},
           "tag": {"type": "array", "description": "describe the dataset (source, environment, ...): KEY=VALUE (repeatable)", "items": {"type": "string"}, "x-metavar": "KEY=VALUE"},
           "dedup": {"type": "string", "enum": ["exact", "text"], "description": "drop records whose body repeats"},
           "fieldset": {"type": "string", "description": "the field set (data/fields/<id>.yaml) declaring the item fields"},
           "field": {"type": "array", "items": {"type": "string"}, "description": "a record field to keep as an item field (repeatable; default: every field the --fieldset declares)"},
           "hide_text": {"type": "boolean", "description": "text: hidden: none of its text on any public surface"},
           "description": {"type": "string", "default": "", "description": "what the dataset is"},
           "force": {"type": "boolean", "description": "overwrite an existing dataset nothing cites yet"},
       }),
    Op("arm-from-capture", "work", "production's recorded decisions as an arm, scored like any (no call)",
       "POST", "/captures/{capture}/arms", "evaluation_harness.arm_from_capture:body", "",
       locks=(("captures", False), ("dataset:{dataset_id}", True), ("system:{as}", True)), required=("dataset_id", "capture", "as",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset the arm's run is on"},
           "capture": {"type": "string", "description": "the capture whose records hold production's decisions"},
           "as": {"type": "string", "description": "the system's id (e.g. production_2026_11_v1)"},
           "like": {"type": "string", "description": "the deployed system, by its id: its adapter is taken"},
           "field": {"type": "string", "description": "the record's field holding the output, when the adapter has no recorded_output"},
           "goal": {"type": "string", "description": "the goal its run is measured for"},
           "labels": {"type": "string", "x-metavar": "SET", "description": "score against this label set of the dataset (RFC-023)"},
       }),
    Op("importer-check", "work", "check an importer: its records are well-formed, ids unique, two reads the same",
       "POST", "/importers/{importer}/check", "evaluation_harness.importer_check:body", "",
       locks=(), required=("importer", "query",), inputs={
           "importer": {"type": "string", "description": "a built-in name or a project importer's name (a code file, path.py:Class, is never taken by a job)", "pattern": "^[a-z0-9][a-z0-9_]*$"},
           "query": {"type": "string", "description": "the query: JSON (a file, @file.json, is never taken by a job)", "pattern": "^(?!@)"},
           "limit": {"type": "integer", "description": "check only the first N records"},
       }),
)  # fmt: skip
